package app.snaptocart.config; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));} }
